const input=$input.first()?.json ?? {};
  return [{json:{
    requiredTag:String(input.requiredTag ?? 'docs-internal'),
    projectTagPrefix:String(input.projectTagPrefix ?? 'project:'),
    projectSlug:String(input.projectSlug ?? '').trim().toLowerCase(),
    aiMode:String(input.aiMode ?? 'bootstrap'),
    documentationMode:String(input.documentationMode ?? 'core')
  }}];

const cfg=$('Configuração').first().json;
  const workflows=$input.all().map(item=>item.json);
  const normalize=value=>String(value??'').trim().toLowerCase();
  const slugify=value=>String(value??'')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()
    .replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'workflow';
  const titleFromSlug=slug=>slug.split('-').filter(Boolean)
    .map(part=>part.charAt(0).toUpperCase()+part.slice(1)).join(' ');

  const documented=workflows.filter(workflow=>
    (workflow.tags??[]).some(tag=>normalize(tag.name??tag)===normalize(cfg.requiredTag))
  );

  const invalid=[];
  const groups=new Map();
  for(const workflow of documented){
    const projectTags=(workflow.tags??[])
      .map(tag=>String(tag.name??tag))
      .filter(name=>normalize(name).startsWith(normalize(cfg.projectTagPrefix)));
    if(projectTags.length!==1){
      invalid.push({workflowId:workflow.id,name:workflow.name,projectTags});
      continue;
    }
    const projectSlug=slugify(projectTags[0].slice(cfg.projectTagPrefix.length));
    if(cfg.projectSlug&&projectSlug!==slugify(cfg.projectSlug)) continue;
    if(!groups.has(projectSlug)) groups.set(projectSlug,[]);
    groups.get(projectSlug).push(workflow);
  }

  if(invalid.length){
    throw new Error('Workflows com docs-internal precisam de exatamente uma tag project:<slug>: '+
      invalid.map(item=>item.name).join(', '));
  }
  if(cfg.projectSlug&&!groups.has(slugify(cfg.projectSlug))){
    throw new Error('Projeto não encontrado para a tag project:'+slugify(cfg.projectSlug));
  }
  if(groups.size===0){
    return [{json:{kind:'empty',requiredTag:cfg.requiredTag,discovered:workflows.length,message:'Nenhum projeto documentável encontrado.'}}];
  }

  const sensitiveKey=/(authorization|api.?key|token|secret|password|cookie|private.?key|client.?secret|workflow.?id|spreadsheet.?id|document.?id|folder.?id|database.?id|prompt|messages|system.?message|json.?schema.?example)/i;
  const placeholder=key=>'{{'+String(key||'SECRET').replace(/[^a-z0-9]+/gi,'_').toUpperCase()+'}}';

  function sanitize(value,key=''){
    if(sensitiveKey.test(key)) return placeholder(key);
    if(Array.isArray(value)) return value.map(entry=>sanitize(entry,key));
    if(value&&typeof value==='object'){
      return Object.fromEntries(Object.entries(value).map(([childKey,childValue])=>[childKey,sanitize(childValue,childKey)]));
    }
    if(typeof value!=='string') return value;
    return value
      .replace(/Bearer\s+[A-Za-z0-9._~+\/=\-]+/gi,'Bearer {{AUTH_TOKEN}}')
      .replace(/https?:\/\/(?:localhost|127\.0\.0\.1|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+)(?::\d+)?/gi,'https://internal.example');
  }

  function publicNode(node){
    const allowed=['id','name','type','typeVersion','position','disabled','notes','notesInFlow','executeOnce','retryOnFail','maxTries','waitBetweenTries','onError'];
    const clean=Object.fromEntries(allowed.filter(key=>node[key]!==undefined).map(key=>[key,node[key]]));
    clean.parameters=sanitize(node.parameters??{});
    if(/(?:^|\.)webhook$|formTrigger$/i.test(node.type)&&clean.parameters.path) clean.parameters.path='WEBHOOK_PATH';
    if(/chainLlm/i.test(node.type)&&clean.parameters.text) clean.parameters.text='{{TEXT}}';
    if(node.credentials){
      clean.credentials=Object.fromEntries(Object.keys(node.credentials).sort().map(type=>[
        type,{id:type.toUpperCase()+'_CREDENTIAL_ID',name:type.toUpperCase()+'_CREDENTIAL'}
      ]));
    }
    return clean;
  }

  function stableValue(value){
    if(Array.isArray(value)) return value.map(stableValue);
    if(value&&typeof value==='object'){
      return Object.fromEntries(Object.keys(value).sort().map(key=>[key,stableValue(value[key])]));
    }
    return value;
  }

  function stableHash(value){
    const text=JSON.stringify(stableValue(value));
    let first=2166136261;
    let second=3339675911;
    for(let index=0;index<text.length;index++){
      const code=text.charCodeAt(index);
      first=Math.imul(first^code,16777619);
      second=Math.imul(second^code,2246822519);
    }
    return (first>>>0).toString(16).padStart(8,'0')+(second>>>0).toString(16).padStart(8,'0');
  }

  function roleOf(workflow){
    const tags=(workflow.tags??[]).map(tag=>normalize(tag.name??tag));
    if(tags.includes('component:agent')) return 'agent';
    if(tags.includes('component:tool')) return 'tool';
    if(tags.includes('component:subflow')) return 'subflow';
    return 'workflow';
  }

  function workflowReference(node){
    if(!/(executeWorkflow|toolWorkflow)/i.test(node.type)) return null;
    const raw=node.parameters?.workflowId;
    const value=typeof raw==='string'?raw:raw?.value;
    if(typeof value!=='string'||!value||value.startsWith('=')) return null;
    return value;
  }

  const outputs=[];
  for(const [projectSlug,projectWorkflows] of [...groups.entries()].sort(([a],[b])=>a.localeCompare(b))){
    const byId=new Map(projectWorkflows.map(item=>[item.id,item]));
    const usedSlugs=new Set();
    const components=[];

    for(const item of [...projectWorkflows].sort((a,b)=>a.name.localeCompare(b.name))){
      let workflowSlug=slugify(item.name);
      if(usedSlugs.has(workflowSlug)) workflowSlug=workflowSlug+'-'+stableHash(item.id).slice(0,6);
      usedSlugs.add(workflowSlug);
      const role=roleOf(item);
      const publicWorkflow={
        name:item.name,
        nodes:(item.nodes??[]).map(publicNode),
        connections:item.connections??{},
        settings:{executionOrder:item.settings?.executionOrder??'v1'}
      };
      const functionalWorkflow={
        name:item.name,
        nodes:(item.nodes??[]).map(node=>({
          name:node.name,
          type:node.type,
          typeVersion:node.typeVersion,
          disabled:Boolean(node.disabled),
          parameters:sanitize(node.parameters??{}),
          credentialTypes:Object.keys(node.credentials??{}).sort()
        })).sort((a,b)=>a.name.localeCompare(b.name)),
        connections:item.connections??{},
        settings:{executionOrder:item.settings?.executionOrder??'v1'}
      };
      components.push({
        workflowId:item.id,
        workflowSlug,
        componentId:role+'.'+workflowSlug,
        role,
        name:item.name,
        tags:(item.tags??[]).map(tag=>tag.name??tag).sort(),
        sourceUpdatedAt:item.updatedAt,
        nodeCount:(item.nodes??[]).length,
        functionalHash:stableHash(functionalWorkflow),
        publicWorkflow,
        original:item
      });
    }

    const componentByWorkflowId=new Map(components.map(component=>[component.workflowId,component]));
    const dependencies=[];
    for(const component of components){
      for(const node of component.original.nodes??[]){
        const targetId=workflowReference(node);
        if(!targetId) continue;
        const target=componentByWorkflowId.get(targetId);
        dependencies.push({
          source:component.componentId,
          relation:/toolWorkflow/i.test(node.type)?'usesTool':'callsSubflow',
          viaNode:node.name,
          target:target?.componentId??null,
          targetWorkflowId:targetId,
          external:!target
        });
      }
    }

    const projectHash=stableHash({
      projectSlug,
      components:components.map(component=>({
        componentId:component.componentId,
        functionalHash:component.functionalHash
      })).sort((a,b)=>a.componentId.localeCompare(b.componentId)),
      dependencies:dependencies.map(item=>({
        source:item.source,relation:item.relation,target:item.target,targetWorkflowId:item.targetWorkflowId
      })).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)))
    });

    const projectTitle=titleFromSlug(projectSlug);
    const projectManifest={
      schemaVersion:1,
      projectSlug,
      title:projectTitle,
      sourceOfTruth:'github',
      bootstrapCompleted:false,
      aiMode:cfg.aiMode,
      currentVersion:null,
      functionalHash:projectHash,
      workflows:components.map(component=>({
        workflowId:component.workflowId,
        workflowSlug:component.workflowSlug,
        componentId:component.componentId,
        role:component.role,
        name:component.name,
        tags:component.tags,
        nodeCount:component.nodeCount,
        functionalHash:component.functionalHash,
        sourceUpdatedAt:component.sourceUpdatedAt
      })),
      dependencies,
      reviewRequired:true
    };

    const technicalFiles={
      'project.json':JSON.stringify(projectManifest,null,2)
    };
    for(const component of components){
      technicalFiles['workflows/'+component.workflowSlug+'.sanitized.json']=JSON.stringify(component.publicWorkflow,null,2);
    }

    outputs.push({json:{
      kind:'project',
      projectSlug,
      title:projectTitle,
      functionalHash:projectHash,
      aiMode:cfg.aiMode,
      reviewRequired:true,
      components:projectManifest.workflows,
      dependencies,
      humanFiles:{},
      technicalFiles
    }});
  }
  return outputs;

const rows=$input.all().map(item=>item.json);
  const projects=rows.filter(row=>row.kind==='project');
  const empty=rows.find(row=>row.kind==='empty');
  return [{json:{
    status:'core-ready',
    selectedProjects:projects.length,
    payloads:projects,
    projects:projects.map(project=>({
      projectSlug:project.projectSlug,
      title:project.title,
      functionalHash:project.functionalHash,
      workflows:project.components.length,
      humanFiles:Object.keys(project.humanFiles),
      technicalFiles:Object.keys(project.technicalFiles),
      reviewRequired:project.reviewRequired
    })),
    discoveredWorkflows:empty?.discovered,
    message:empty?.message??'Projetos agrupados e arquivos preparados; nenhuma publicação foi realizada.'
  }}];
